def add(p,t,a,prose,src,role='clarification',relation='direct_tafsir',tradition='dirayet',status='explicit',priority='extended',audience='general',**kw):
 codes={'tafsir':'TAF','reader_note':'READ','method_note':'MET','novelty':'NOV','revelation_history':'REV','asbab':'ASB','hadith':'HAD','source_note':'SRC','qiraat':'QIR','historical_context':'HIS','semantic_history':'SEM','nazm':'NAZ','cross_quran':'QUR','modern_scholarship':'MOD'}
 counts[t]+=1;d=dict(id=f'S107-{codes[t]}-{counts[t]:03}',type=t,tradition=tradition,ayah=a,role=role,relation=relation,status=status,priority=priority,audience=audience,prose=prose,source=src);d.update(kw);A[p].append(d)
