def block(d):
 def val(k,v):
  if isinstance(v,bool):return 'true' if v else 'false'
  return v if k in check.ENUMS else json.dumps(v,ensure_ascii=False)
 assert all('\n' not in str(v) for v in d.values())
 return '{'+', '.join(k+':'+val(k,v) for k,v in d.items())+'}'
